    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)

    L = n.bit_length()

    positions = []
    temp = n
    pos = 1
    while temp > 0:
        if temp & 1:
            positions.append(pos)
        temp >>= 1
        pos += 1

    output = [str(L)]
    for p in reversed(positions):
        if p != L:
            output.append(str(p))

    sys.stdout.write(" ".join(output) + "\n")

