    main()

import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)

    bit_length = n.bit_length()
    out = [str(bit_length)]

    for k in range(bit_length - 1, 0, -1):
        if (n >> (k - 1)) & 1:
            out.append(str(k))

    sys.stdout.write(" ".join(out) + "\n")

if __name__ == "__main__":
    main()

